import React,{useRef} from 'react'
import './contact.css'
import {AiOutlineMail} from 'react-icons/ai'
import {BsMessenger,BsWhatsapp} from 'react-icons/bs'
import emailjs from 'emailjs-com';

const data = [
    {
        icon:<AiOutlineMail className='contact_option-icon'/>,
        title:'Email',
        content:'zakariaebouanane@gmail.com',
        url:'mailto:zakariaebouanane@gmail.com'
    },
    {
        icon: <BsMessenger className='contact_option-icon'/>,
        title:'Messenger',
        content:'zakariae bouanane',
        url:'https://m.me/zakariae.bouanane'
    },
    {
        icon: <BsWhatsapp className='contact_option-icon'/>,
        title:'WhatsApp',
        content:'+212682****',
        url:' https://wa.me/+212682133822'
    }
]

function Contact() {
    const form = useRef();

    const sendEmail = (e) => {
        e.preventDefault();

        emailjs.sendForm('service_u5ksgbd', 'template_x2qnsef', form.current , 'A4eAkultIq0y382KH')
        
        e.target.reset()
    };


    return (
        <section id='contact'>
            <h5>Get in Touch</h5>
            <h2>Contact Me</h2>

            <div className="container contact_ct">
                <div className="contact_options">
                    {
                        data.map(({icon,title,content,url},index)=>{
                            return(
                                <article className="contact_option" key={index}>
                                    {icon}
                                    <h4>{title}</h4>
                                    <h5>{content}</h5>
                                    <a href={url} target='_blank'>Send a Message</a>
                                </article>
                            )
                        })
                    }
                    
                </div>

                <form ref={form} onSubmit={sendEmail}>                    
                    <input type="text" name='name' placeholder='Your Full Name' required />
                    <input type="email" name='email' placeholder='Your Email' required />
                    <textarea name="message" rows="7" required placeholder='Your Message'></textarea>
                    <button type='submit' className='btn btn-primary'>Send Message</button>
                </form>
            </div>
        </section>
    )
}

export default Contact