import React from 'react'
import './experience.css'
import {BsPatchCheckFill} from 'react-icons/bs'

function Experience() {

    //Levels : Expert,Advanced,Intermediate,Basic

    const Exp = {

        backend:[{name:'PHP',level:'Intermediate'},{name:'JAVA',level:'Intermediate'},{name:'.NET',level:'Intermediate'},{name:'Symfony',level:'Intermediate'},{name:'Spring boot',level:'Intermediate'}],

        database:[{name:'MySQL',level:'Advanced'},{name:'SQL server',level:'Intermediate'},{name:'MongoDB',level:'Basic'}],

    frontend:[{name:'REACT',level:'Intermediate'},{name:'Angular',level:'Intermediate'},{name:'Tailwind',level:'Intermediate'},{name:'BS5',level:'Advanced'},{name:'JS',level:'Advanced'}],
    
    exp:[{name:'UML',level:'Intermediate'},{name:'Docker',level:'Intermediate'},{name:'Jira',level:'Intermediate'},{name:'SCRUM',level:'Intermediate'},{name:'Git , GitLab',level:'Intermediate'}]
    
    
            }

    return (
        <section id='experience'>
            <h5>What Skills I Have </h5>
            <h2>My Experience</h2>

            <div className="container exp_container">
                                
                <div className="exp_frontend">
                    <h3>Frontend Devlopment</h3>
                    
                    <div className="exp_content">
                            
                            { Exp.frontend.map((lang,key)=>{
                                
                                return(

                                    <article className="exp_details" key={key}>
                                        <BsPatchCheckFill className='exp_details-icon'/>
                                        <div>
                                            <h4>{lang.name}</h4>
                                            <small className='text-light'>{lang.level}</small>
                                        </div>
                                    </article>

                                )
                            }) }
                            
                            
                    </div>
                </div>

                

                <div className="exp_backend">
                    <h3>Backend Devlopment</h3>
                        
                        <div className="exp_content">
                                
                                { Exp.backend.map((lang,key)=>{

                                    return(

                                        <article className="exp_details" key={key}>
                                            <BsPatchCheckFill className='exp_details-icon'/>
                                            <div>
                                                <h4>{lang.name}</h4>
                                                <small className='text-light'>{lang.level}</small>
                                            </div>
                                        </article>

                                    )

                                }) 
                                
                                
                                
                                }
                                
                                
                        </div>
                    </div>




                <div className="exp_backend">
                    <h3>Database</h3>

                    <div className="exp_content">

                        { Exp.database.map((lang,key)=>{

                            return(

                                <article className="exp_details" key={key}>
                                    <BsPatchCheckFill className='exp_details-icon'/>
                                    <div>
                                        <h4>{lang.name}</h4>
                                        <small className='text-light'>{lang.level}</small>
                                    </div>
                                </article>

                            )

                        })



                        }


                    </div>
                </div>


                    <div className="exp_frontend">

                    <h3>Development Methodologies And Tools</h3>
                    
                    <div className="exp_content">
                            
                            { Exp.exp.map((lang,key)=>{
                                
                                return(

                                    <article className="exp_details" key={key}>
                                        <BsPatchCheckFill className='exp_details-icon'/>
                                        <div>
                                            <h4>{lang.name}</h4>
                                            <small className='text-light'>{lang.level}</small>
                                        </div>
                                    </article>

                                )
                            }) }
                            
                            
                    </div>
                </div>
            </div>
        </section>
    )
}

export default Experience