import React from 'react'
import './portfolio.css'
import img1 from '../../assets/login_flahti.jpg'
import img2 from '../../assets/ofppt.jpg'
import img3 from '../../assets/volkswagen.jpg'
import img4 from '../../assets/sqli.jpg'

const data = [
    {
        id:1,
        image:img4,
        title:'Medical Management - SQli',
        github:'https://github.com/zakariae-bouanane/Internal_medical_managment_system--SQLi',
        demo:'#'

    } ,

    {
        id:2,
        image:img1,
        title:'Flahti - Microservice System (PFA)',
        github:'https://github.com/zakariae-bouanane/Flahti-pfa_4th_year',
        demo:'#'

    } ,

    {
        id:3,
        image:img2,
        title:'Absence Management - OFPPT',
        github:'https://github.com/zakariae-bouanane/Stage-Gestion_d_absences_des_etudiant',
        demo:'#'

    } ,
    {
        id:4,
        image:img3,
        title:'Appointment Management - Atelier Volkswagen',
        github:'https://github.com/zakariae-bouanane/Gestion-des-rendez-vous---volkswwagen',
        demo:'#'

    } ,
]


function Portfolio() {
    return(
        <section id='portfolio'>
            <h5>My Recent Work</h5>
            <h2>Portfolio</h2>

            <div className="container port_container">
                
                {data.map(({id,image,title,github,demo})=>{
                    return(
                        <article className="port_item" key={id}>
                            <div className="port_item-img">
                                <img src={image} alt={image} />
                            </div>
                            
                            <h3>{title}</h3>

                            <div className="port_item-cta">
                                <a href={github} className='btn' target='_blank'>Github</a>
                                <a href={demo}  target='_blank'  className="btn btn-primary disabled">Live Demo</a>
                            </div>
                        </article>
                    )
                })}
                
            </div>
        </section>
    )
}

export default Portfolio