import React from 'react'
import './services.css'

import {BiCheck} from 'react-icons/bi'

function Services() {
    return (
        <section id='services'>
            <h5>What I Offre</h5>
            <h2>Services</h2>

            <div className="container ser_container">
                
                <article className="service">
                    <div className="ser_head">
                        <h3>Modeling and Design</h3>
                    </div>

                    <ul className="ser_list">
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p> Design and modeling using UML for software applications. </p>
                        </li>
                        
                    </ul>
                </article>

                <article className="service">
                    <div className="ser_head">
                        <h3>Analysis and Problem Solving</h3>
                    </div>

                    <ul className="ser_list">
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p>In-depth analysis to optimize processes and performance.</p>
                        </li>
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p>Identifying and efficiently resolving issues related to computer systems.</p>
                        </li>
                        
                    </ul>
                </article>

                <article className="service">
                    <div className="ser_head">
                        <h3>Web Development</h3>
                    </div>

                    <ul className="ser_list">
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p>I can build a <b>Personal</b> , <b>Business</b> , <b>Informational</b> , <b>Blog</b> and <b>Portfolio</b> websites  </p>
                        </li>
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p>I customize websites to meet your specific needs </p>
                        </li>
                        <li>
                            <BiCheck className='ser_list-icon'/>
                            <p>Responsive Design </p>
                        </li>
                        
                    </ul>
                </article>
            </div>
        </section>
    )
}

export default Services